// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/farmer/me", wrapper.GetMyHome)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/farmer/me", wrapper.UpdateMyProfile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/me/complete-profile", wrapper.CompleteMyProfile)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/farmer/me/consents", wrapper.ListMyConsents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/me/consents", wrapper.SetMyConsent)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/me/photo/upload-url", wrapper.CreateMyPhotoUpload)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/me/plots", wrapper.AddMyPlot)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/me/plots/{plot_id}/seasons", wrapper.StartMySeason)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/farmer/me/seasons/{season_id}/close", wrapper.CloseMySeason)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/farmer/fas", wrapper.ListMyFAs)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/fa/farmers/{farmer_id}/photo/upload-url", wrapper.CreateFarmerPhotoUpload)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/fa/farmers/lookup", wrapper.LookupFarmerPhone)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/farmers/stats", wrapper.GetFarmerStats)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/farmers", wrapper.ListFarmers)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/farmers/{farmer_id}", wrapper.GetFarmer360)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/admin/farmers/{farmer_id}", wrapper.UpdateFarmer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/farmers/{farmer_id}/deactivate", wrapper.DeactivateFarmer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/farmers/{farmer_id}/reactivate", wrapper.ReactivateFarmer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/farmer-reassignments", wrapper.ReassignFarmers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/season-rollovers", wrapper.RolloverSeason)
	})

	return r
}

