// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ReassignFarmers Reassign farmers to another FA
	// (POST /v1/admin/farmer-reassignments)
	ReassignFarmers(ctx context.Context, request ReassignFarmersRequestObject) (ReassignFarmersResponseObject, error)
	// ListFarmers List farmers
	// (GET /v1/admin/farmers)
	ListFarmers(ctx context.Context, request ListFarmersRequestObject) (ListFarmersResponseObject, error)
	// GetFarmerStats Farmer numbers for the overview
	// (GET /v1/admin/farmers/stats)
	GetFarmerStats(ctx context.Context, request GetFarmerStatsRequestObject) (GetFarmerStatsResponseObject, error)
	// GetFarmer360 Farmer 360
	// (GET /v1/admin/farmers/{farmer_id})
	GetFarmer360(ctx context.Context, request GetFarmer360RequestObject) (GetFarmer360ResponseObject, error)
	// UpdateFarmer Edit a farmer
	// (PATCH /v1/admin/farmers/{farmer_id})
	UpdateFarmer(ctx context.Context, request UpdateFarmerRequestObject) (UpdateFarmerResponseObject, error)
	// DeactivateFarmer Deactivate a farmer
	// (POST /v1/admin/farmers/{farmer_id}/deactivate)
	DeactivateFarmer(ctx context.Context, request DeactivateFarmerRequestObject) (DeactivateFarmerResponseObject, error)
	// ReactivateFarmer Reactivate a farmer
	// (POST /v1/admin/farmers/{farmer_id}/reactivate)
	ReactivateFarmer(ctx context.Context, request ReactivateFarmerRequestObject) (ReactivateFarmerResponseObject, error)
	// RolloverSeason Close every active season of a season code
	// (POST /v1/admin/season-rollovers)
	RolloverSeason(ctx context.Context, request RolloverSeasonRequestObject) (RolloverSeasonResponseObject, error)
	// LookupFarmerPhone Is this phone number already registered?
	// (GET /v1/fa/farmers/lookup)
	LookupFarmerPhone(ctx context.Context, request LookupFarmerPhoneRequestObject) (LookupFarmerPhoneResponseObject, error)
	// CreateFarmerPhotoUpload Get a presigned upload URL for a farmer's photo
	// (POST /v1/fa/farmers/{farmer_id}/photo/upload-url)
	CreateFarmerPhotoUpload(ctx context.Context, request CreateFarmerPhotoUploadRequestObject) (CreateFarmerPhotoUploadResponseObject, error)
	// ListMyFAs Look for FAs
	// (GET /v1/farmer/fas)
	ListMyFAs(ctx context.Context, request ListMyFAsRequestObject) (ListMyFAsResponseObject, error)
	// GetMyHome Farmer home
	// (GET /v1/farmer/me)
	GetMyHome(ctx context.Context, request GetMyHomeRequestObject) (GetMyHomeResponseObject, error)
	// UpdateMyProfile Update my profile
	// (PATCH /v1/farmer/me)
	UpdateMyProfile(ctx context.Context, request UpdateMyProfileRequestObject) (UpdateMyProfileResponseObject, error)
	// CompleteMyProfile Complete a self sign-up
	// (POST /v1/farmer/me/complete-profile)
	CompleteMyProfile(ctx context.Context, request CompleteMyProfileRequestObject) (CompleteMyProfileResponseObject, error)
	// ListMyConsents My current consents
	// (GET /v1/farmer/me/consents)
	ListMyConsents(ctx context.Context, request ListMyConsentsRequestObject) (ListMyConsentsResponseObject, error)
	// SetMyConsent Grant or withdraw a consent
	// (POST /v1/farmer/me/consents)
	SetMyConsent(ctx context.Context, request SetMyConsentRequestObject) (SetMyConsentResponseObject, error)
	// CreateMyPhotoUpload Get a presigned upload URL for my photo
	// (POST /v1/farmer/me/photo/upload-url)
	CreateMyPhotoUpload(ctx context.Context, request CreateMyPhotoUploadRequestObject) (CreateMyPhotoUploadResponseObject, error)
	// AddMyPlot Add a plot
	// (POST /v1/farmer/me/plots)
	AddMyPlot(ctx context.Context, request AddMyPlotRequestObject) (AddMyPlotResponseObject, error)
	// StartMySeason Start a crop season on a plot
	// (POST /v1/farmer/me/plots/{plot_id}/seasons)
	StartMySeason(ctx context.Context, request StartMySeasonRequestObject) (StartMySeasonResponseObject, error)
	// CloseMySeason Close an active season
	// (POST /v1/farmer/me/seasons/{season_id}/close)
	CloseMySeason(ctx context.Context, request CloseMySeasonRequestObject) (CloseMySeasonResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

